        .piece:hover {
            transform: scale(1.1);
        }

        .piece:active {
            cursor: grabbing;
            transform: scale(1.15);
        }

        .piece.dragging {
            opacity: 0.4;
        }

        .piece.white-piece {
            cursor: grab;
        }

        .piece.black-piece {
            cursor: not-allowed;
            opacity: 0.9;
        }

