            margin-top: 30px;
            font-size: 28px;
            font-weight: bold;
            min-height: 40px;
            text-align: center;
            padding: 15px 30px;
            border-radius: 8px;
            backdrop-filter: blur(10px);
            transition: all 0.3s;
